SELECT * FROM BIZ_SIGN_RECORD_
WHERE SUB_PROC_INST_ID_ = #{subProcessInstanceId, jdbcType=VARCHAR}
ORDER BY CREATE_TIME_, ID_

SELECT COUNT(*) FROM BIZ_SIGN_RECORD_
WHERE SIGN_ROUND_ID_ = #{signRoundId, jdbcType=VARCHAR}
  AND ADD_USER_ID_ = #{addUserId, jdbcType=VARCHAR}
  AND SIGN_STATUS_ IN ('PENDING', 'APPROVED')

SELECT COUNT(*) FROM BIZ_SIGN_RECORD_
WHERE SOURCE_TASK_ID_ = #{sourceTaskId, jdbcType=VARCHAR}
  AND SIGN_STATUS_ = 'PENDING'

mapper.update:
UPDATE BIZ_SIGN_RECORD_
SET SIGN_STATUS_ = 'CANCELLED',
    UPDATE_TIME_ = #{finishTime, jdbcType=TIMESTAMP},
    FINISH_TIME_ = #{finishTime, jdbcType=TIMESTAMP}
WHERE SOURCE_TASK_ID_ = #{sourceTaskId, jdbcType=VARCHAR}
  AND SIGN_STATUS_ = 'PENDING'
